from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


class Group:
    def __init__(self, members: list[str]) -> None:
        self._members = tuple(dict.fromkeys(members))
        self._balances = {member: 0 for member in self._members}
        self._expenses: list[dict] = []

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
        description: str = "",
    ) -> None:
        if payer not in self._balances:
            raise ValueError("Payer is not a group member")

        if participants is None:
            participants = list(self._members)
        if not participants:
            raise ValueError("An expense must have at least one participant")
        if any(participant not in self._balances for participant in participants):
            raise ValueError("Participant is not a group member")

        try:
            value = Decimal(str(amount))
            if not value.is_finite() or value <= 0:
                raise ValueError("Amount must be positive and finite")
            cents = int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        except (InvalidOperation, TypeError) as exc:
            raise ValueError("Invalid amount") from exc

        share = cents // len(participants)
        self._balances[payer] += cents
        for participant in participants:
            self._balances[participant] -= share

        # Any remainder belongs to the payer rather than being distributed.
        self._balances[payer] -= cents - share * len(participants)

        self._expenses.append(
            {
                "payer": payer,
                "amount": amount,
                "participants": list(participants),
                "description": description,
            }
        )

    def expenses(self) -> list[dict]:
        return [
            {**expense, "participants": list(expense["participants"])}
            for expense in self._expenses
        ]

    def balances(self) -> dict[str, float]:
        return {member: cents / 100 for member, cents in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        debtors = sorted(
            ([member, -balance] for member, balance in self._balances.items() if balance < 0),
            key=lambda item: item[1],
            reverse=True,
        )
        creditors = sorted(
            ([member, balance] for member, balance in self._balances.items() if balance > 0),
            key=lambda item: item[1],
            reverse=True,
        )

        payments = []
        debtor_index = creditor_index = 0

        while debtor_index < len(debtors) and creditor_index < len(creditors):
            debtor, debt = debtors[debtor_index]
            creditor, credit = creditors[creditor_index]

            if debt < 100:
                debtor_index += 1
                continue
            if credit < 100:
                creditor_index += 1
                continue

            payment = min(debt, credit)
            payments.append((debtor, creditor, payment / 100))
            debtors[debtor_index][1] -= payment
            creditors[creditor_index][1] -= payment

            if debtors[debtor_index][1] == 0:
                debtor_index += 1
            if creditors[creditor_index][1] == 0:
                creditor_index += 1

        return payments
